#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
__device__ __forceinline__ int floor_div(int a, int b) {
    int q = a / b;
    int r = a - q * b;
    if (r != 0 && ((r < 0) != (b < 0))) {
        q -= 1;
    }
    return q;
}
#define TILE_H 16
#define TILE_W 16
#define OW_PER_THREAD 4
#define OH_PER_THREAD 4
__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_h,
    const int in_w,
    const int out_h,
    const int out_w,
    const int kH,
    const int kW,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dil_h,
    const int dil_w,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const int in_tile_h,
    const int in_tile_w
) {
    extern __shared__ float smem[]; // size: in_channels_per_group * in_tile_h * in_tile_w
    int tx = threadIdx.x; // 0..TILE_W-1
    int ty = threadIdx.y; // 0..TILE_H-1
    int ow0 = blockIdx.x * TILE_W * OW_PER_THREAD;
    int oh0 = blockIdx.y * TILE_H * OH_PER_THREAD;
    int bz = blockIdx.z;
    int n = bz / groups;
    int g = bz % groups;
    // base of the required input tile for this block (safe upper-bound sized)
    int ih_min = floor_div(oh0 + pad_h - (kH - 1) * dil_h, stride_h);
    int iw_min = floor_div(ow0 + pad_w - (kW - 1) * dil_w, stride_w);
    int tile_size = in_channels_per_group * in_tile_h * in_tile_w;
    int weight_tile_size = in_channels_per_group * out_channels_per_group * kH * kW;
    float* smem_input = smem;
    float* smem_weight = smem + tile_size;
    int tid = ty * TILE_W + tx;
    int nthreads = TILE_W * TILE_H;
    for (int idx = tid; idx < tile_size; idx += nthreads) {
        int iw_off = idx % in_tile_w;
        int tmp = idx / in_tile_w;
        int ih_off = tmp % in_tile_h;
        int ic_local = tmp / in_tile_h;
        int ih = ih_min + ih_off;
        int iw = iw_min + iw_off;
        int ic = g * in_channels_per_group + ic_local;
        float val = 0.0f;
        if (ih >= 0 && ih < in_h && iw >= 0 && iw < in_w) {
            int input_idx = ((n * in_channels + ic) * in_h + ih) * in_w + iw;
            val = input[input_idx];
        }
        smem_input[(ic_local * in_tile_h + ih_off) * in_tile_w + iw_off] = val;
    }
    int weight_base = g * in_channels_per_group * out_channels_per_group * kH * kW;
    if (((weight_tile_size & 3) == 0) && ((tile_size & 3) == 0)) {
        int weight_tile_size_vec = weight_tile_size >> 2;
        const float4* weight_vec_ptr = reinterpret_cast<const float4*>(weight + weight_base);
        float4* smem_weight_vec = reinterpret_cast<float4*>(smem_weight);
        for (int idx = tid; idx < weight_tile_size_vec; idx += nthreads) {
            smem_weight_vec[idx] = weight_vec_ptr[idx];
        }
    } else {
        for (int idx = tid; idx < weight_tile_size; idx += nthreads) {
            smem_weight[idx] = weight[weight_base + idx];
        }
    }
    __syncthreads();
    int ohv[OH_PER_THREAD];
    bool oh_validv[OH_PER_THREAD];
    #pragma unroll
    for (int rh = 0; rh < OH_PER_THREAD; ++rh) {
        ohv[rh] = oh0 + ty + rh * TILE_H;
        oh_validv[rh] = ohv[rh] < out_h;
    }
    int owv[OW_PER_THREAD];
    bool ow_validv[OW_PER_THREAD];
    #pragma unroll
    for (int r = 0; r < OW_PER_THREAD; ++r) {
        owv[r] = ow0 + tx + r * TILE_W;
        ow_validv[r] = owv[r] < out_w;
    }
    const int MAX_KDIM = 16;
    int ih_offset_table[MAX_KDIM][OH_PER_THREAD];
    bool kh_valid_table[MAX_KDIM][OH_PER_THREAD];
    bool any_kh_valid_table[MAX_KDIM];
    for (int kh = 0; kh < kH; ++kh) {
        bool any_kh_valid = false;
        #pragma unroll
        for (int rh = 0; rh < OH_PER_THREAD; ++rh) {
            int off_val = -1;
            bool valid = false;
            if (oh_validv[rh]) {
                int oh_off = ohv[rh] + pad_h - kh * dil_h;
                if (oh_off % stride_h == 0) {
                    int ih = oh_off / stride_h;
                    int off = ih - ih_min;
                    if (off >= 0 && off < in_tile_h) {
                        off_val = off;
                        valid = true;
                        any_kh_valid = true;
                    }
                }
            }
            ih_offset_table[kh][rh] = off_val;
            kh_valid_table[kh][rh] = valid;
        }
        any_kh_valid_table[kh] = any_kh_valid;
    }
    int iw_offset_table[MAX_KDIM][OW_PER_THREAD];
    bool kw_valid_table[MAX_KDIM][OW_PER_THREAD];
    bool any_kw_valid_table[MAX_KDIM];
    for (int kw = 0; kw < kW; ++kw) {
        bool any_valid = false;
        #pragma unroll
        for (int r = 0; r < OW_PER_THREAD; ++r) {
            int off_val = -1;
            bool valid = false;
            if (ow_validv[r]) {
                int ow_off = owv[r] + pad_w - kw * dil_w;
                if (ow_off % stride_w == 0) {
                    int iw = ow_off / stride_w;
                    int off = iw - iw_min;
                    if (off >= 0 && off < in_tile_w) {
                        off_val = off;
                        valid = true;
                        any_valid = true;
                    }
                }
            }
            iw_offset_table[kw][r] = off_val;
            kw_valid_table[kw][r] = valid;
        }
        any_kw_valid_table[kw] = any_valid;
    }
    for (int oc_in_group = 0; oc_in_group < out_channels_per_group; ++oc_in_group) {
        float acc[OH_PER_THREAD][OW_PER_THREAD];
        #pragma unroll
        for (int rh = 0; rh < OH_PER_THREAD; ++rh) {
            #pragma unroll
            for (int r = 0; r < OW_PER_THREAD; ++r) acc[rh][r] = 0.0f;
        }
        int oc = g * out_channels_per_group + oc_in_group;
        for (int kh = 0; kh < kH; ++kh) {
            if (!any_kh_valid_table[kh]) continue;
            for (int kw = 0; kw < kW; ++kw) {
                if (!any_kw_valid_table[kw]) continue;
                for (int ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
                    int weight_idx = ((ic_local * out_channels_per_group + oc_in_group) * kH + kh) * kW + kw;
                    float wv = smem_weight[weight_idx];
                    #pragma unroll
                    for (int rh = 0; rh < OH_PER_THREAD; ++rh) {
                        if (!kh_valid_table[kh][rh]) continue;
                        int ih_offset = ih_offset_table[kh][rh];
                        const float* smem_row = smem_input + (ic_local * in_tile_h + ih_offset) * in_tile_w;
                        #pragma unroll
                        for (int r = 0; r < OW_PER_THREAD; ++r) {
                            if (kw_valid_table[kw][r]) {
                                float in_val = smem_row[iw_offset_table[kw][r]];
                                acc[rh][r] += in_val * wv;
                            }
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int rh = 0; rh < OH_PER_THREAD; ++rh) {
            if (!oh_validv[rh]) continue;
            #pragma unroll
            for (int r = 0; r < OW_PER_THREAD; ++r) {
                if (ow_validv[r]) {
                    int out_idx = ((n * out_channels + oc) * out_h + ohv[rh]) * out_w + owv[r];
                    output[out_idx] = acc[rh][r];
                }
            }
        }
    }
}
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
) {
    input = input.contiguous();
    weight = weight.contiguous();
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);
    const int kH = weight.size(2);
    const int kW = weight.size(3);
    const int out_channels_per_group = weight.size(1);
    const int out_channels = out_channels_per_group * groups;
    const int in_channels_per_group = in_channels / groups;
    const int out_h = (in_h - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1;
    const int out_w = (in_w - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1;
    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());
    // safe upper bound for the required input tile size along each dimension
    int in_tile_h = (TILE_H * OH_PER_THREAD - 1 + (kH - 1) * dil_h + stride_h - 1) / stride_h + 2;
    int in_tile_w = (TILE_W * OW_PER_THREAD - 1 + (kW - 1) * dil_w + stride_w - 1) / stride_w + 2;
    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (out_w + TILE_W * OW_PER_THREAD - 1) / (TILE_W * OW_PER_THREAD),
        (out_h + TILE_H * OH_PER_THREAD - 1) / (TILE_H * OH_PER_THREAD),
        batch_size * groups
    );
    size_t smem_bytes = (size_t)(in_channels_per_group * in_tile_h * in_tile_w + in_channels_per_group * out_channels_per_group * kH * kW) * sizeof(float);
    conv_transpose2d_kernel<<<grid, block, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_h,
        in_w,
        out_h,
        out_w,
        kH,
        kW,
        stride_h,
        stride_w,
        pad_h,
        pad_w,
        dil_h,
        dil_w,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        in_tile_h,
        in_tile_w
    );
    return output;
}
"""

